from pathlib import Path
import json,html
base=Path(__file__).parent
concepts=[
('01','Signal hardware','Tactile aluminum, sage and a physical connection metaphor.','image'),
('02','Editorial connection','Large serif typography with warm light and rich ink themes.','image'),
('03','Electric blue relay','Oversized cobalt wordmark and a sculptural signal conduit.','image'),
('04','Quiet desktop','Restrained product photography and a physical Copy key.','image'),
('05','Paper airwave','Warm folded-paper illustration linking two devices.','image'),
('06','Mint laboratory','Precise technical composition and a tactile clipboard control.','coded'),
('07','Sunset studio','Bold coral editorial rhythm and graphic product details.','coded'),
('08','Ink & porcelain','Confident monochrome typography and a quiet notification strip.','coded'),
('09','Plum instrument','Aubergine materials and instrument-inspired controls.','coded'),
('10','Cyan blueprint','Crisp signal diagrams and a cool technical palette.','coded')]
buttons=[]; panels=[]
for ident,name,desc,kind in concepts:
 buttons.append(f'<button role="tab" aria-controls="panel-{ident}" aria-selected="{str(ident=="06").lower()}" tabindex="{0 if ident=="06" else -1}" id="tab-{ident}" data-option="{ident}"><span>{ident}</span>{html.escape(name)}</button>')
 folder='images' if kind=='image' else 'flash'
 pictures=''.join(f'<img class="theme-{theme}" src="{folder}/{ident}-{theme}.png" alt="{html.escape(name)} hero in {theme} theme" width="1586" height="992">' for theme in ['dark','light'])
 panels.append(f'<section role="tabpanel" aria-labelledby="tab-{ident}" id="panel-{ident}" class="option {"active" if ident=="06" else ""}" data-id="{ident}"><div class="caption"><div><strong>{ident} / {html.escape(name)}</strong><span class="frame-label" data-frame="{ident}">{ident}D · Dark theme</span><p>{html.escape(desc)}</p></div><span class="provenance">{"Codex-directed image concept" if kind=="image" else "Gemini 3.8 Flash · coded screenshot"}</span></div><div class="picture">{pictures}</div></section>')
styles='''
:root{--font-sans:"Adwaita Sans","Segoe UI",sans-serif;--font-mono:"Adwaita Mono",monospace;--ink:var(--foreground,#f2f3ef);--dim:var(--muted-foreground,#a8afa8);--edge:var(--border,#3b423d);--tint:var(--secondary,#1f2923);--green:var(--primary,#b4d5a1);--green-ink:var(--primary-foreground,#15200f);--radius:12px;color-scheme:dark}
html,body{margin:0;padding:0;background:transparent;color:var(--ink);font-family:var(--font-sans);line-height:1.4}*{box-sizing:border-box}button{font:inherit;color:inherit;cursor:pointer}button:focus-visible{outline:2px solid var(--green);outline-offset:3px}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0 0 14px}.subtle{font-size:12px;color:var(--dim)}.controls{display:flex;gap:6px}.controls button{border:1px solid var(--edge);border-radius:8px;background:transparent;padding:8px 12px;font-size:12px}.controls button[aria-pressed=true]{background:var(--green);color:var(--green-ink);border-color:var(--green)}.tabs{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px;margin-bottom:18px}.tabs button{min-width:0;text-align:left;display:flex;flex-direction:column;gap:3px;border:1px solid var(--edge);border-radius:10px;background:transparent;padding:9px 10px;font-size:11px;min-height:58px}.tabs button span{font:12px var(--font-mono);color:var(--dim)}.tabs button[aria-selected=true]{border-color:var(--green);background:var(--tint)}.tabs button[aria-selected=true] span{color:var(--green)}.option{display:none}.option.active{display:block}.caption{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:12px}.caption strong{font-size:16px;font-weight:600}.frame-label{display:block;font:11px var(--font-mono);margin-top:3px;color:var(--dim)}.caption p{margin:4px 0 0;font-size:12px;color:var(--dim)}.provenance{font:10px var(--font-mono);color:var(--dim);text-align:right;max-width:150px;padding-top:3px}.picture{border:1px solid var(--edge);border-radius:var(--radius);overflow:hidden;background:var(--tint)}img{display:block;width:100%;height:auto;object-fit:contain}.theme-light{display:none}[data-gallery-theme=light] .theme-light{display:block}[data-gallery-theme=light] .theme-dark{display:none}.bottom{display:flex;justify-content:space-between;gap:12px;align-items:center;margin:14px 0 8px}.arrows{display:flex;gap:8px}.arrows button,.shortlist{padding:9px 12px;border:1px solid var(--edge);border-radius:9px;background:transparent;font-size:12px}.shortlist[aria-pressed=true]{background:var(--green);color:var(--green-ink)}.notes{font-size:11px;color:var(--dim);margin:10px 0 0}.selection{font-size:12px;color:var(--ink);min-height:18px;margin-top:12px}a{color:inherit} @media(max-width:520px){.tabs{grid-template-columns:repeat(2,minmax(0,1fr))}.tabs button{min-height:45px;flex-direction:row;align-items:center;gap:8px}.caption{flex-direction:column}.provenance{text-align:left;max-width:none}.toolbar{align-items:flex-start}.subtle{max-width:155px}.bottom{align-items:flex-start}.caption strong{font-size:15px}}
'''
script='''
let current=5;const ids=['01','02','03','04','05','06','07','08','09','10'];let chosen=[];const tabs=[...document.querySelectorAll('[data-option]')];const shortlist=document.querySelector('.shortlist');function updateSelection(){const frame=ids[current]+(document.documentElement.dataset.galleryTheme==='light'?'L':'D');const yes=chosen.includes(frame);shortlist.setAttribute('aria-pressed',String(yes));shortlist.textContent=(yes?'✓ Shortlisted ':'Shortlist ')+frame;document.getElementById('selection').textContent=chosen.length?'Your shortlist: '+chosen.join(', ')+'. Reply with these numbers in chat.':'Choose a direction, or shortlist a few. Your choice is not sent until you reply in chat.';}function show(i){current=(i+10)%10;tabs.forEach((b,n)=>{b.setAttribute('aria-selected',String(n===current));b.tabIndex=n===current?0:-1});document.querySelectorAll('.option').forEach((p,n)=>p.classList.toggle('active',n===current));updateSelection()}tabs.forEach((b,n)=>{b.addEventListener('click',()=>show(n));b.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();show(current+(e.key==='ArrowRight'?1:-1));tabs[current].focus()}})});document.getElementById('previous').onclick=()=>show(current-1);document.getElementById('next').onclick=()=>show(current+1);document.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>{document.documentElement.dataset.galleryTheme=b.dataset.themeChoice;document.querySelectorAll('[data-frame]').forEach(x=>x.textContent=x.dataset.frame+(b.dataset.themeChoice==='dark'?'D · Dark theme':'L · Light theme'));document.querySelectorAll('[data-theme-choice]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));updateSelection()});shortlist.onclick=()=>{const id=ids[current]+(document.documentElement.dataset.galleryTheme==='light'?'L':'D');chosen=chosen.includes(id)?chosen.filter(x=>x!==id):[...chosen,id].sort();updateSelection()};updateSelection();
'''
page='<!doctype html><html lang="en" data-gallery-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pingora · ten hero directions</title><style>'+styles+'</style></head><body><main><div class="toolbar"><span class="subtle">10 directions · choose a number<br>Each includes light + dark</span><div class="controls" aria-label="Preview theme"><button data-theme-choice="dark" aria-pressed="true">Dark</button><button data-theme-choice="light" aria-pressed="false">Light</button></div></div><nav class="tabs" role="tablist" aria-label="Hero design options">'+''.join(buttons)+'</nav>'+''.join(panels)+'<div class="bottom"><div class="arrows"><button id="previous" aria-label="Previous concept">← Previous</button><button id="next" aria-label="Next concept">Next →</button></div><button class="shortlist" aria-pressed="false">Shortlist 01</button></div><div id="selection" class="selection" aria-live="polite"></div><p class="notes">01–05 are generated design images; 06–10 are screenshots of coded concepts. All product UI is illustrative. No design is selected yet. Hardware in 01 is a visual metaphor, not a physical Pingora product.</p></main><script>'+script+'</script></body></html>'
page=page.replace('src="images/05-light.png"','src="images/display-05-light.png"')
(base/'index.html').write_text(page)
(base/'concepts.json').write_text(json.dumps([{'id':i,'name':n,'description':d,'kind':k} for i,n,d,k in concepts],indent=2)+'\n')
print('Gallery source generated: ten options, paired theme images')
